				for (Name n : typeArgsForToBuilder) {
					lb.append(maker.TypeParameter(n, List.<JCExpression>nil()));
				}
				tps = lb.toList();
			}
			JCMethodDecl md = generateToBuilderMethod(job, tps, annInstance.setterPrefix());
			if (md != null) {
